/* 小手机智能家电：网页经 Windows 助手，私人 iOS 直接经 HomeKit；两条通道都以真实回读为准。 */
(function(){
'use strict';
var ENDPOINT=(typeof COMPANION_URL==='string'?COMPANION_URL.replace(/\/+$/,''):'')+'/functions/v1/phone-smart-home';
var COLORS={pink:['粉色',335,60],rose:['玫红色',345,70],red:['红色',0,75],orange:['橙色',28,80],yellow:['黄色',52,75],green:['绿色',120,65],cyan:['青色',185,65],blue:['蓝色',215,70],purple:['紫色',282,58],white:['白色',0,0]};
var memory={status:null,state:null,lights:[],busy:false,error:'',pair:null};
function clean(v,n){return String(v==null?'':v).trim().slice(0,n||200);}
function privateMode(){return typeof window!=='undefined'&&window.__SMALL_PHONE_PRIVATE__===true;}
function nativeHome(){return privateMode()&&window.SmallPhoneNative&&typeof window.SmallPhoneNative.request==='function';}
function randomHex(bytes){try{var a=new Uint8Array(bytes);crypto.getRandomValues(a);return Array.from(a).map(function(x){return x.toString(16).padStart(2,'0');}).join('');}catch(_){return String(uid()+uid()+uid()).toLowerCase().replace(/[^a-z0-9]/g,'').padEnd(bytes*2,'0').slice(0,bytes*2);}}
function identity(){var target='',secret='';try{target=localStorage.getItem('north_smart_home_target_v1')||'';secret=localStorage.getItem('north_smart_home_owner_secret_v1')||'';}catch(_){}
  if(!/^yb_[a-z0-9]{20,96}$/.test(target)){target='yb_'+randomHex(24);try{localStorage.setItem('north_smart_home_target_v1',target);}catch(_){}}
  if(secret.length<24){secret='shc_'+randomHex(32);try{localStorage.setItem('north_smart_home_owner_secret_v1',secret);}catch(_){}}
  return{target:target,ownerSecret:secret};
}
function requestKey(){return'shr_'+(crypto&&crypto.randomUUID?crypto.randomUUID():randomHex(20));}
function delay(ms){return new Promise(function(resolve){setTimeout(resolve,ms);});}
function message(error){var raw=clean(error&&error.message||error,220);if(/Failed to fetch|NetworkError|Load failed|fetch/i.test(raw))return'网络连接失败，未执行灯具操作';if(!privateMode()&&/device-required|还没有|智能家电电脑/.test(raw))return'还没有连接 Windows 智能家电助手';return raw||'智能家电服务暂不可用';}
async function call(action,payload,opt){opt=opt||{};var id=identity(),key=opt.requestKey||'',deadline=Date.now()+(opt.timeout||22000);do{var controller=typeof AbortController==='function'?new AbortController():null,timer=controller?setTimeout(function(){controller.abort();},Math.min(12000,Math.max(1500,deadline-Date.now()))):0,response,body;try{var headers={'content-type':'application/json'};if(typeof COMPANION_KEY==='string'){headers.apikey=COMPANION_KEY;headers.Authorization='Bearer '+COMPANION_KEY;}response=await fetch(ENDPOINT,{method:'POST',headers:headers,body:JSON.stringify({action:action,payload:payload||{},client:{target:id.target,ownerSecret:id.ownerSecret,appVersion:String(typeof APP_VER==='string'?APP_VER:''),requestKey:key}}),signal:controller&&controller.signal});try{body=await response.json();}catch(_){body=null;}}catch(error){if(timer)clearTimeout(timer);throw new Error(error&&error.name==='AbortError'?'智能家电请求超时，未确认成功':message(error));}if(timer)clearTimeout(timer);if(response.status===202&&body&&body.pending===true&&Date.now()<deadline){await delay(850);continue;}if(!response.ok||!body||body.ok!==true)throw new Error(message(body&&body.error||('智能家电服务 HTTP '+response.status)));return body.data==null?body:body.data;}while(Date.now()<deadline);throw new Error('电脑助手响应超时，未确认灯具状态');}
function settings(){S.settings=S.settings||{};var h=S.settings.smartHomeWeb&&typeof S.settings.smartHomeWeb==='object'?S.settings.smartHomeWeb:(S.settings.smartHomeWeb={});h.name=clean(h.name,30)||'小灯';if(!h.homeKitTarget||typeof h.homeKitTarget!=='object')h.homeKitTarget={accessoryId:'',serviceId:''};return h;}
function saveLocal(){try{save();}catch(_){}}
function setBusy(on,error){memory.busy=!!on;memory.error=clean(error,220);renderIfOpen();}
function renderIfOpen(){try{if(typeof cur==='function'&&cur().p==='wxsmarthome')render();}catch(_){}}
function actualColor(state){if(!state)return null;var sat=Number(state.saturation),hue=Number(state.hue);if(!Number.isFinite(sat)||!Number.isFinite(hue))return null;if(sat<12)return{key:'white',label:'白色'};hue=(hue%360+360)%360;var key=hue>=320&&hue<345?'pink':hue>=345&&hue<355?'rose':hue>=355||hue<12?'red':hue<42?'orange':hue<75?'yellow':hue<165?'green':hue<200?'cyan':hue<255?'blue':'purple';return{key:key,label:COLORS[key][0]};}
function stateText(s){if(!s)return'尚未读取';var rows=[s.power===true?'已开灯':s.power===false?'已关灯':'开关未知'];if(Number.isFinite(Number(s.brightness)))rows.push('亮度 '+Math.round(Number(s.brightness))+'%');var color=actualColor(s);if(color)rows.push(color.label);return rows.join(' · ');}
function selectedLight(){var t=settings().homeKitTarget;return memory.lights.find(function(x){return String(x.accessoryId||'')===String(t.accessoryId||'')&&String(x.serviceId||'')===String(t.serviceId||'');})||null;}
function rememberLight(light){if(!light)return;var t=settings().homeKitTarget;t.accessoryId=String(light.accessoryId||'');t.serviceId=String(light.serviceId||'');saveLocal();}
function applyNativeSnapshot(result){if(!result||result.ok!==true||!Array.isArray(result.lights))throw new Error(message(result&&result.message||'没有取得苹果家庭的真实状态'));memory.lights=result.lights.filter(function(x){return x&&x.accessoryId&&x.serviceId;});var light=selectedLight();if(!light&&memory.lights.length===1){light=memory.lights[0];rememberLight(light);}memory.state=light||null;memory.status={channel:'homekit',authorized:true,linked:!!light,online:!!(light&&light.reachable===true&&light.complete===true),count:memory.lights.length,readAt:String(result.readAt||light&&light.readAt||'')};if(!memory.lights.length)memory.error='苹果家庭中没有发现可控制的灯具';else if(!light)memory.error='发现多盏灯，请选择要控制的灯具';else if(light.reachable!==true)memory.error='这盏灯当前离线';else if(light.complete!==true)memory.error='灯具真实状态读取不完整';else memory.error='';return memory.status;}
function statusText(){if(memory.busy)return privateMode()?'正在读取苹果家庭':'正在等待电脑真实回读';if(memory.error)return memory.error;if(!memory.status)return privateMode()?'尚未连接苹果家庭':'尚未检查电脑助手';if(!memory.status.linked)return privateMode()?'已允许家庭访问，请选择灯具':'尚未连接 Windows 助手';if(!memory.status.online)return privateMode()?'HomeKit 灯具暂不可用':'电脑助手离线';return memory.state?(privateMode()?'HomeKit 已连接 · ':'已连接 · ')+stateText(memory.state):(privateMode()?'等待苹果家庭状态':'电脑助手在线，等待读取');}
async function refreshStatus(readLamp){setBusy(true,'');try{if(privateMode()){if(!nativeHome())throw new Error('当前私人包没有载入 HomeKit 原生桥');var snap=await window.SmallPhoneNative.request('homekit.lights.snapshot',{});return applyNativeSnapshot(snap);}memory.status=await call('device_status',{});if(readLamp&&memory.status.linked&&memory.status.online){var result=await call('snapshot',{}, {requestKey:requestKey(),timeout:35000});if(!result||result.verified!==true||!result.state)throw new Error('电脑没有返回可验证的真实状态');memory.state=result.state;}return memory.status;}catch(error){memory.error=message(error);throw error;}finally{memory.busy=false;renderIfOpen();}}
function nativePayload(action,data){var light=selectedLight();if(!light)return null;return Object.assign({accessoryId:String(light.accessoryId),serviceId:String(light.serviceId),action:action},data||{});}
async function nativeAction(action,data){var payload=nativePayload(action,data);if(!payload)return{ok:false,verified:false,message:'请先允许家庭访问并选择灯具'};var result;try{result=await window.SmallPhoneNative.request('homekit.light.command',payload);}catch(error){return{ok:false,verified:false,message:message(error)};}if(result&&result.state){memory.state=result.state;var at=memory.lights.findIndex(function(x){return String(x.accessoryId)===String(result.state.accessoryId)&&String(x.serviceId)===String(result.state.serviceId);});if(at>=0)memory.lights[at]=result.state;}if(!result||result.ok!==true||result.verified!==true||!result.state)return{ok:false,verified:false,message:message(result&&result.message||'HomeKit 没有确认真实状态'),state:result&&result.state};memory.status={channel:'homekit',authorized:true,linked:true,online:true,count:memory.lights.length,readAt:String(result.verifiedAt||result.state.readAt||'')};return result;}
async function executeNative(plan){if(!nativeHome())return{ok:false,verified:false,message:'当前私人包没有载入 HomeKit 原生桥'};if(!selectedLight()){try{await refreshStatus(true);}catch(error){return{ok:false,verified:false,message:memory.error||message(error)};}if(!selectedLight())return{ok:false,verified:false,message:memory.error||'请先选择灯具'};}var actions=[];if(plan.power!==undefined)actions.push(['power',{value:plan.power==='on'||plan.power===true}]);if(plan.brightness!==undefined)actions.push(['brightness',{value:Math.max(1,Math.min(100,Math.round(Number(plan.brightness)||1)))}]);if(plan.color!==undefined&&COLORS[plan.color])actions.push(['color',{hue:COLORS[plan.color][1],saturation:COLORS[plan.color][2]}]);else if(plan.hue!==undefined&&plan.saturation!==undefined)actions.push(['color',{hue:Number(plan.hue),saturation:Number(plan.saturation)}]);if(plan.warmth!==undefined)actions.push(['temperature',{warmth:Number(plan.warmth)}]);if(!actions.length)return{ok:false,verified:false,message:'没有可执行的灯具动作'};var last=null;for(var i=0;i<actions.length;i++){last=await nativeAction(actions[i][0],actions[i][1]);if(!last||last.ok!==true||last.verified!==true)return last;}return{ok:true,verified:true,state:last.state,message:'HomeKit 真实状态已回读'};}
async function execute(plan){if(memory.busy)throw new Error('上一条灯具操作还没有结束');setBusy(true,'');try{if(privateMode()){var nativeResult=await executeNative(plan);if(!nativeResult.verified)memory.error=message(nativeResult.message);else memory.error='';return nativeResult;}var result=await call('control',{plan:plan},{requestKey:requestKey(),timeout:45000});if(!result||result.ok!==true||result.verified!==true||!result.state)throw new Error('没有取得灯具真实成功回读');memory.state=result.state;memory.status=Object.assign({},memory.status||{},{linked:true,online:true});return{ok:true,verified:true,state:result.state,message:'真实状态已回读'};}catch(error){memory.error=message(error);return{ok:false,verified:false,message:memory.error};}finally{memory.busy=false;renderIfOpen();}}
function pageNav(){return'<div class="wx-directory-head wx-smart-home-nav"><div class="wx-real-nav titled"><button onclick="back()">‹</button><b>智能家电</b><span></span></div></div>';}
function icon(){return'<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M9 30 32 10l23 20v25H39V40H25v15H9V30Z"/></svg>';}
function renderControls(s,disabled,brightness,color){return'<div class="wx-smart-home-power"><button '+(disabled?'disabled':'')+' onclick="wxSmartHomeControl({power:\'off\'})" class="'+(s&&s.power===false?'on':'')+'">关灯</button><button '+(disabled?'disabled':'')+' onclick="wxSmartHomeControl({power:\'on\'})" class="'+(s&&s.power===true?'on':'')+'">开灯</button></div><label class="wx-smart-home-slider"><span>亮度</span><b>'+brightness+'%</b><input type="range" min="1" max="100" value="'+brightness+'" '+(disabled?'disabled':'')+' onchange="wxSmartHomeBrightness(this.value)"></label><div class="wx-smart-home-colors" aria-label="颜色">'+Object.keys(COLORS).map(function(key){return'<button '+(disabled?'disabled':'')+' class="c-'+key+' '+(color&&color.key===key?'on':'')+'" title="'+COLORS[key][0]+'" onclick="wxSmartHomeColor(\''+key+'\')"></button>';}).join('')+'</div>';}
function renderWxSmartHome(){var h=settings(),s=memory.state,isPrivate=privateMode(),linked=!!(memory.status&&memory.status.linked),online=!!(memory.status&&memory.status.online),disabled=memory.busy||!linked||!online,brightness=Math.max(1,Math.min(100,Math.round(Number(s&&s.brightness)||30))),color=actualColor(s);setTimeout(function(){if(!memory.status&&!memory.busy&&(!isPrivate||h.homeKitTarget.accessoryId))refreshStatus(true).catch(function(){});},40);var panel;if(linked){panel=renderControls(s,disabled,brightness,color)+'<div class="wx-smart-home-actions"><button '+(memory.busy?'disabled':'')+' onclick="wxSmartHomeRefresh()">重新读取真实状态</button>'+(isPrivate&&memory.lights.length>1?'<button onclick="wxSmartHomeChoose()">更换灯具</button>':!isPrivate?'<button class="danger" onclick="wxSmartHomeUnlink()">解除电脑连接</button>':'')+'</div>';}else if(isPrivate){panel='<div class="wx-smart-home-pair-copy"><p>点击后由 iPhone 弹出“家庭”访问许可。允许后小手机会直接读取家庭 App 里的灯具，不需要连接电脑。</p><button onclick="wxSmartHomeConnect()" '+(memory.busy?'disabled':'')+'>允许访问苹果家庭</button>'+(memory.lights.length>1?'<button onclick="wxSmartHomeChoose()">选择灯具</button>':'')+'</div>';}else{panel='<div class="wx-smart-home-pair-copy"><p>网页版通过 Windows 智能家电助手连接实灯；电脑与灯保持在同一路由器下。</p><button onclick="wxSmartHomePairCode()" '+(memory.busy?'disabled':'')+'>生成十位配对码</button></div>';}return pageNav()+'<div class="scroll wx-smart-home-page"><section class="wx-smart-home-hero"><small>我的家</small><h1>'+esc(s&&s.roomName||'卧室')+'</h1><div class="wx-smart-home-house">'+icon()+'</div><button class="wx-smart-home-name" onclick="wxSmartHomeRename()">'+esc(h.name)+'</button><p>'+esc(statusText())+'</p></section><section class="wx-smart-home-panel"><header><div><small>真实设备控制</small><h2>'+esc(linked?(isPrivate?'iPhone · HomeKit 直连':'Windows 实灯控制'):(isPrivate?'连接苹果家庭':'连接电脑助手'))+'</h2></div><span class="'+(online?'online':'')+'">'+esc(online?'在线':'未连接')+'</span></header>'+panel+(memory.error?'<div class="wx-smart-home-error">'+esc(memory.error)+'</div>':'')+'</section><p class="wx-smart-home-foot">'+(isPrivate?'私人版直接使用 iPhone 的家庭权限；每次操作都由 HomeKit 写入并重新读取真实状态，不依赖电脑。':'网页版由电脑助手执行并重新读取灯具；电脑关机、离线或超时会如实显示失败。')+'</p></div>';}
async function connectNative(){setBusy(true,'');try{if(!nativeHome())throw new Error('当前私人包没有载入 HomeKit 原生桥');var snap=await window.SmallPhoneNative.request('homekit.lights.snapshot',{});applyNativeSnapshot(snap);if(memory.lights.length>1&&!selectedLight()){renderIfOpen();chooseLight();return false;}if(memory.status&&memory.status.linked){toast('苹果家庭已连接，灯具真实状态已读取');return true;}throw new Error(memory.error||'没有发现可控制的灯具');}catch(error){memory.error=message(error);toast(memory.error);return false;}finally{memory.busy=false;renderIfOpen();}}
function chooseLight(){if(!memory.lights.length)return toast('请先允许访问苹果家庭并读取灯具');openModal('<h3>选择要控制的灯具</h3><div class="hint">以下设备直接来自 iPhone 家庭 App；小手机只保存设备标识，不保存配对码。</div>'+memory.lights.map(function(x,i){return'<button class="btn g" style="margin-top:8px" onclick="wxSmartHomeChooseAt('+i+')">'+esc(String(x.homeName||'家庭'))+' · '+esc(String(x.roomName||'未分配房间'))+' · '+esc(String(x.accessoryName||x.serviceName||'灯具'))+'</button>';}).join('')+'<div class="btns"><button class="btn g" onclick="closeModal()">取消</button></div>');}
function chooseLightAt(index){var light=memory.lights[Math.max(0,Math.floor(Number(index)||0))];if(!light)return;rememberLight(light);memory.state=light;memory.status={channel:'homekit',authorized:true,linked:true,online:light.reachable===true&&light.complete===true,count:memory.lights.length,readAt:String(light.readAt||'')};memory.error=memory.status.online?'':light.reachable!==true?'这盏灯当前离线':'灯具真实状态读取不完整';closeModal();renderIfOpen();toast(memory.status.online?'灯具已选择，真实状态已读取':memory.error);}
async function pairCode(){if(privateMode())return connectNative();setBusy(true,'');try{var result=await call('pairing_begin',{});memory.pair=result;var code=clean(result&&result.pairCode,10);if(!/^\d{10}$/.test(code))throw new Error('云端没有生成有效配对码');openModal('<h3>连接 Windows 助手</h3><div class="hint">在电脑打开“小手机智能家电助手”，输入下面十位数字。配对码十分钟后失效；不要把它发给别人。</div><div class="wx-smart-home-code">'+esc(code.replace(/(\d{5})(\d{5})/,'$1 $2'))+'</div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="wxSmartHomePairCheck()">电脑已输入，检查连接</button></div>');}catch(error){memory.error=message(error);toast(memory.error);}finally{memory.busy=false;renderIfOpen();}}
async function pairCheck(){try{await refreshStatus(true);if(memory.status&&memory.status.linked){closeModal();toast(privateMode()?'苹果家庭已连接，真实状态已读取':'电脑助手已连接，真实灯具状态已读取');}else toast(privateMode()?'尚未选择灯具':'电脑还没有完成配对');}catch(error){toast(message(error));}}
function rename(){var current=settings().name;openModal('<h3>给小灯改名</h3><div class="field"><input id="wx-smart-home-rename" maxlength="30" value="'+esc(current)+'" placeholder="例如：床头小灯"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="wxSmartHomeRenameSave()">保存</button></div>');}
function renameSave(){var input=document.getElementById('wx-smart-home-rename'),value=clean(input&&input.value,30);if(!value)return toast('请填写名字');settings().name=value;saveLocal();closeModal();renderIfOpen();}
async function control(plan){var result=await execute(plan);toast(result.verified?'真实状态已回读，操作成功':result.message);return result;}
async function unlink(){if(privateMode()){settings().homeKitTarget={accessoryId:'',serviceId:''};memory.status={channel:'homekit',authorized:true,linked:false,online:false,count:memory.lights.length};memory.state=null;saveLocal();renderIfOpen();return chooseLight();}if(!confirm('确定解除小手机与这台 Windows 助手的连接吗？灯具和官方控制不会受影响。'))return;setBusy(true,'');try{await call('device_revoke',{confirmedByUser:true});memory.status={linked:false,online:false};memory.state=null;toast('已解除电脑助手连接');}catch(error){memory.error=message(error);toast(memory.error);}finally{memory.busy=false;renderIfOpen();}}
window.renderWxSmartHome=renderWxSmartHome;
window.wxSmartHomeConnect=connectNative;window.wxSmartHomeChoose=chooseLight;window.wxSmartHomeChooseAt=chooseLightAt;
window.wxSmartHomePairCode=pairCode;window.wxSmartHomePairCheck=pairCheck;window.wxSmartHomeRename=rename;window.wxSmartHomeRenameSave=renameSave;
window.wxSmartHomeRefresh=function(){refreshStatus(true).then(function(){toast('已重新读取真实状态');}).catch(function(error){toast(message(error));});};
window.wxSmartHomeControl=control;window.wxSmartHomeBrightness=function(value){return control({brightness:Math.max(1,Math.min(100,Math.round(Number(value)||1)))});};window.wxSmartHomeColor=function(value){return COLORS[value]?control({color:value}):Promise.resolve({ok:false,verified:false,message:'不支持的颜色'});};window.wxSmartHomeUnlink=unlink;
window.wxSmartHomeRoleAvailable=function(){return !!(memory.status&&memory.status.linked&&memory.status.online);};
window.wxSmartHomeRoleContext=function(){return{name:settings().name,state:memory.state,status:memory.status};};
window.wxSmartHomeRoleExecute=execute;
setTimeout(function(){if(!privateMode()||settings().homeKitTarget.accessoryId)refreshStatus(false).catch(function(){});},1200);
setInterval(function(){if(!memory.busy&&(!privateMode()||settings().homeKitTarget.accessoryId))refreshStatus(false).catch(function(){});},20000);
if(typeof window.addEventListener==='function')window.addEventListener('small-phone-native-ready',function(){if(privateMode()&&settings().homeKitTarget.accessoryId)refreshStatus(true).catch(function(){});});
})();
